// Some portions generated by Codex

const test = require('node:test');
const assert = require('node:assert/strict');
const { loadWorker } = require('./row-store-worker-harness.js');

test('row identity worker keeps a bounded baseline and filters against it', async () => {
    const worker = loadWorker();
    let requestId = 0;
    const send = (message) => worker.send({ requestId: ++requestId, indexId: 'baseline-1', ...message });

    assert.equal((await send({ op: 'identity-create' })).ok, true);
    const added = await send({ op: 'identity-add', keys: ['iri:a', 'blank:repo:b', 'iri:a'] });
    assert.equal(added.baselineRows, 3);
    assert.ok(added.addedBytes > 0, 'the worker reports the persistent key reservation');

    const filtered = await send({ op: 'identity-filter', keys: ['iri:a', 'literal:a', 'blank:repo:b'] });
    assert.deepEqual(Array.from(filtered.unseen), [1]);

    const disposed = await send({ op: 'identity-dispose' });
    assert.equal(disposed.disposed, true);
});

test('row identity worker rejects a baseline larger than 10,000 input rows', async () => {
    const worker = loadWorker();
    let requestId = 0;
    const send = (message) => worker.send({ requestId: ++requestId, indexId: 'baseline-2', ...message });
    assert.equal((await send({ op: 'identity-create' })).ok, true);

    let baselineRows = 0;
    while (baselineRows < 10000) {
        const count = Math.min(256, 10000 - baselineRows);
        const keys = Array.from({ length: count }, (_, index) => 'row:' + (baselineRows + index));
        const result = await send({ op: 'identity-add', keys });
        assert.equal(result.ok, true);
        baselineRows += count;
    }
    const overflow = await send({ op: 'identity-add', keys: ['row:overflow'] });
    assert.equal(overflow.ok, false);
    assert.match(overflow.error, /10,000/);
});
